-- =====================================================================
-- 469 Gap ID: per-organization sequential G-001 on custom_gap
--
-- SIR'S INSTRUCTION
-- ------------------
--   Gaps must carry a per-organization unique id in the format G-001
--   (G- + 3-digit sequential number), restarting at 001 per
--   organization, generated by the backend, and shown as a column in
--   the Gap Centre grid. Same shape 378 gave Risk (R-001) and Risk
--   Candidate (RC-001).
--
-- WHY A TRIGGER, NOT INLINE IN THE CREATE PROC (as 378 did for Risk)
-- ------------------------------------------------------------------
--   378 could allocate inline because risk_register has exactly ONE
--   insert point (sp_risk_register_insert). custom_gap does NOT -- it is
--   inserted from several live procedures (sp_custom_gap_open,
--   sp_custom_gap_save, sp_custom_gap_materialize_for_instance,
--   sp_custom_gap_generate_from_assurance_observation,
--   sp_org_assurance_observation_accept), with no shared choke point.
--   Re-issuing all of them verbatim to add two lines each is far more
--   invasive and error-prone than one AFTER INSERT trigger that fills
--   the number on every path, present and future. The allocation logic
--   (MAX+1 per org under UPDLOCK/HOLDLOCK, FORMAT(n,'000')) is the exact
--   same mechanism 139 (PR_nnn instance codes) and 378 use.
--
-- NUMBERING
-- ---------
--   * Per organization, independent sequence. SUBSTRING(gap_number,3,20)
--     is the numeric part after the 'G-' prefix.
--   * FORMAT(@n,'000') pads to 3 digits and overflows past 999 on its
--     own (G-1000), so the sequence never runs out.
--   * Column is NULLable (an AFTER INSERT trigger cannot fill a NOT NULL
--     column -- NOT NULL is checked before the trigger runs), but the
--     trigger populates it synchronously inside the same transaction, so
--     a row is never observed without a number. A FILTERED unique index
--     (WHERE gap_number IS NOT NULL) enforces uniqueness per org and is
--     the backstop alongside the UPDLOCK/HOLDLOCK.
--
-- Idempotent / safe to re-run. ASCII-only.
-- DEPENDS ON: 054 (custom_gap table).
-- Rollback: 469_gap_number_per_org_sequential_rollback.sql
-- =====================================================================
SET NOCOUNT ON;
GO

IF OBJECT_ID('grac_practice.custom_gap','U') IS NULL
BEGIN
    RAISERROR('469: grac_practice.custom_gap missing. Run 054 first.', 16, 1);
    SET NOEXEC ON;
END
GO

-- ---------------------------------------------------------------------
-- 1. Column
-- ---------------------------------------------------------------------
IF COL_LENGTH('grac_practice.custom_gap','gap_number') IS NULL
    ALTER TABLE grac_practice.custom_gap ADD gap_number NVARCHAR(20) NULL;
GO

-- ---------------------------------------------------------------------
-- 2. Backfill existing rows -- per organization, numbered in creation
--    order (custom_gap_id ascending), only rows without a number yet.
-- ---------------------------------------------------------------------
;WITH ranked AS (
    SELECT custom_gap_id, gap_number,
           ROW_NUMBER() OVER (PARTITION BY organization_id
                              ORDER BY custom_gap_id) AS rn
    FROM   grac_practice.custom_gap
    WHERE  gap_number IS NULL
)
UPDATE ranked
   SET gap_number = N'G-' + FORMAT(rn, '000');
PRINT '469: custom_gap.gap_number backfilled = ' + CAST(@@ROWCOUNT AS NVARCHAR(20));
GO

-- ---------------------------------------------------------------------
-- 3. Filtered unique index (per org, over populated numbers only).
-- ---------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM sys.indexes
               WHERE name = 'uq_pm_custom_gap_gap_number'
                 AND object_id = OBJECT_ID('grac_practice.custom_gap'))
    CREATE UNIQUE INDEX uq_pm_custom_gap_gap_number
        ON grac_practice.custom_gap(organization_id, gap_number)
        WHERE gap_number IS NOT NULL;
GO

-- ---------------------------------------------------------------------
-- 4. AFTER INSERT trigger -- assign the next per-org G-nnn to every new
--    row that arrives without one, whatever procedure created it.
-- ---------------------------------------------------------------------
CREATE OR ALTER TRIGGER grac_practice.trg_pm_custom_gap_assign_number
ON grac_practice.custom_gap
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted WHERE gap_number IS NULL)
        RETURN;

    ;WITH to_number AS (
        SELECT i.custom_gap_id, i.organization_id,
               ROW_NUMBER() OVER (PARTITION BY i.organization_id
                                  ORDER BY i.custom_gap_id) AS rn
        FROM   inserted i
        WHERE  i.gap_number IS NULL
    ),
    base AS (
        -- Highest G-nnn already used per affected org. UPDLOCK/HOLDLOCK so
        -- two concurrent inserts into one org cannot read the same "next".
        SELECT d.organization_id,
               ISNULL(MAX(TRY_CONVERT(INT, SUBSTRING(g.gap_number, 3, 20))), 0) AS max_no
        FROM   (SELECT DISTINCT organization_id FROM to_number) d
        LEFT   JOIN grac_practice.custom_gap g WITH (UPDLOCK, HOLDLOCK)
               ON  g.organization_id = d.organization_id
               AND g.gap_number LIKE N'G-%'
               AND TRY_CONVERT(INT, SUBSTRING(g.gap_number, 3, 20)) IS NOT NULL
        GROUP BY d.organization_id
    )
    UPDATE g
       SET gap_number = N'G-' + FORMAT(b.max_no + tn.rn, '000')
    FROM   grac_practice.custom_gap g
    JOIN   to_number tn ON tn.custom_gap_id = g.custom_gap_id
    JOIN   base b       ON b.organization_id = tn.organization_id;
END
GO

PRINT '469 complete: custom_gap.gap_number (G-001 per organization) added, backfilled, indexed, and auto-assigned on insert.';
GO
SET NOEXEC OFF;
GO
